import{_ as t,o as s,c as a,a3 as r}from"./chunks/framework.BlfGB29P.js";const g=JSON.parse('{"title":"Widgets interactifs","description":"Universal, curseur radial et comparaison Inventwo depuis Studio 0.1.295.","frontmatter":{"title":"Widgets interactifs","description":"Universal, curseur radial et comparaison Inventwo depuis Studio 0.1.295."},"headers":[],"relativePath":"fr/projects/grafik-visual-studio/interaktiv.md","filePath":"fr/projects/grafik-visual-studio/interaktiv.md","lastUpdated":1792754181000}'),i={name:"fr/projects/grafik-visual-studio/interaktiv.md"};function n(o,e,u,l,d,c){return s(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="widgets-interactifs" tabindex="-1">Widgets interactifs <a class="header-anchor" href="#widgets-interactifs" aria-label="Permalink to &quot;Widgets interactifs&quot;">​</a></h1><p><strong>Studio 0.1.296 :</strong> Les <strong>62 types restants</strong> proposent des propriétés/messages DE/EN/FR, des commandes climatiques facultatives et une vérification des sources, attributs et unités. Projets et versions de paquet existants restent valides ; les nouveaux groupes sont initialement désactivés. <a href="./ha-quellen-climate">Guide et limites</a>. Les tests simulés ne valident pas les appareils réels/Companion. <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/blob/master/ha_grafik_visual_studio/docs/remaining-widget-audit-2026-10-12.md" target="_blank" rel="noreferrer">Rapport</a>.</p><p><strong>Studio 0.1.295</strong> ajoute les grandes fonctions de la <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/blob/master/ha_grafik_visual_studio/docs/inventwo-interactive-audit-2026-10-12.md" target="_blank" rel="noreferrer">comparaison Inventwo VIS-2</a>. <a href="/projects/grafik-visual-studio/interaktiv">Deutsch</a> · <a href="/en/projects/grafik-visual-studio/interaktiv">English</a>.</p><h2 id="universal" tabindex="-1">Universal <a class="header-anchor" href="#universal" aria-label="Permalink to &quot;Universal&quot;">​</a></h2><p>En plus de la commutation et des cycles existants : valeur fixe, maintien avec restauration de la valeur précédente, augmenter/diminuer avec limites, navigation vers des pages Studio, fenêtres configurables et requêtes HTTP. Les anciens boutons conservent leur cycle tant qu’une nouvelle option n’est pas choisie. Groupes et réglages conservés.</p><p>Contenus par défaut/par état : <strong>Vue intégrée</strong>, <strong>Sélecteur de couleur</strong> et <strong>Horloge analogique</strong>. Les vues peuvent s’adapter à la taille ; les récursions sont empêchées. Zone/cercle de couleur, curseurs HSV/RGB, alpha/Kelvin facultatifs. HEX, HEX8, RGB, HSL, HSV et CIE xy peuvent être écrits dans un assistant texte ; les lumières HA reçoivent des commandes RGB/Kelvin validées. Alpha concerne HEX8, pas RGB HA. L’horloge utilise l’heure du navigateur avec chiffres/trotteuse et couleurs configurables.</p><p><strong>Langue interactive</strong> choisit DE/EN/FR pour Universal et les curseurs radiaux, sans traduire les textes utilisateur, noms d’entités/pages ou valeurs techniques.</p><h2 id="curseur-radial-et-apercus" tabindex="-1">Curseur radial et aperçus <a class="header-anchor" href="#curseur-radial-et-apercus" aria-label="Permalink to &quot;Curseur radial et aperçus&quot;">​</a></h2><p>Piste, piste active et curseur acceptent couleurs CSS ou <code>linear-gradient(90deg, red, rgb(255,200,0) 50%, green)</code>, positions en pourcentage et directions comme <code>to top</code>. Héritage des styles et anciennes couleurs conservés.</p><p>Les aperçus interactifs remplissent leur cadre depuis 0.1.294. Depuis 0.1.295 les icônes Material et leur symbole sont aussi agrandis dans la barre latérale et le sélecteur. Seule la mise à jour Studio est nécessaire.</p><h2 id="comportement-et-limites" tabindex="-1">Comportement et limites <a class="header-anchor" href="#comportement-et-limites" aria-label="Permalink to &quot;Comportement et limites&quot;">​</a></h2><p>HTTP GET fonctionne dans le navigateur, avec délai de 15 secondes, sans identifiants Studio ni proxy serveur. CORS et restrictions HTTP/HTTPS s’appliquent. Le PIN de navigation est une barrière d’interface enregistrée dans le projet, pas une autorisation. Un arrêt du navigateur/réseau peut empêcher la restauration du maintien ; prévoir un délai HA pour les appareils critiques.</p><p>Studio utilise les entités HA et pages du projet. Les liaisons ioBroker arbitraires des composantes de couleur et tous les détails d’horloge ne sont pas reproduits ; aucune égalité parfaite des pixels n’est promise. L’interface globale reste DE/EN. <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/blob/master/ha_grafik_visual_studio/docs/universal-0.1.295.md" target="_blank" rel="noreferrer">Guide détaillé DE/EN/FR</a>.</p>',13)])])}const m=t(i,[["render",n]]);export{g as __pageData,m as default};
